namespace CourseCatalog.Models;

public class Department
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Description { get; init; }
}

namespace CourseCatalog.Models;

public class Instructor
{
    public required string Name { get; init; }
    public required string Title { get; init; }
    public required string Email { get; init; }
    public required string Bio { get; init; }
}

namespace CourseCatalog.Models;

public class Course
{
    public required string Id { get; init; }
    public required string Code { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int Credits { get; init; }
    public required string Schedule { get; init; }
    public required string DepartmentId { get; init; }
    public required Instructor Instructor { get; init; }
    public bool IsFeatured { get; init; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string id);
    IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(string id);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = "math", Name = "Mathematics", Description = "Exploration of abstract structures, patterns, and quantitative reasoning." },
            new Department { Id = "eng", Name = "English", Description = "Analysis of literature, writing, and language arts." },
            new Department { Id = "phys", Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces of nature." },
            new Department { Id = "hist", Name = "History", Description = "Examination of past events and their impact on the present." },
        ];

        _courses =
        [
            new Course
            {
                Id = "cs101", Code = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = "cs", IsFeatured = true,
                Instructor = new Instructor { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Email = "alovelace@university.edu", Bio = "Dr. Lovelace specializes in programming language theory and has 15 years of teaching experience. She has published extensively on introductory CS pedagogy." }
            },
            new Course
            {
                Id = "cs201", Code = "CS 201", Title = "Data Structures & Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = "cs", IsFeatured = true,
                Instructor = new Instructor { Name = "Dr. Alan Turing", Title = "Professor", Email = "aturing@university.edu", Bio = "Dr. Turing is a renowned researcher in computational complexity and algorithm optimization. He leads the university's Advanced Computing Lab." }
            },
            new Course
            {
                Id = "cs301", Code = "CS 301", Title = "Database Systems",
                Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = "cs",
                Instructor = new Instructor { Name = "Dr. Edgar Codd", Title = "Professor", Email = "ecodd@university.edu", Bio = "Dr. Codd has over 20 years of experience in database research and has consulted for major technology companies on data architecture." }
            },
            new Course
            {
                Id = "math101", Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = "math", IsFeatured = true,
                Instructor = new Instructor { Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Dr. Noether is an award-winning mathematician whose research spans abstract algebra and theoretical physics." }
            },
            new Course
            {
                Id = "math201", Code = "MATH 201", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = "math",
                Instructor = new Instructor { Name = "Dr. Carl Gauss", Title = "Associate Professor", Email = "cgauss@university.edu", Bio = "Dr. Gauss is a specialist in numerical methods and linear algebra with numerous peer-reviewed publications." }
            },
            new Course
            {
                Id = "eng101", Code = "ENG 101", Title = "College Writing",
                Description = "Develop essential writing skills through essays, research papers, and peer workshops. Emphasis on argumentation and clear prose.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = "eng",
                Instructor = new Instructor { Name = "Prof. Virginia Woolf", Title = "Senior Lecturer", Email = "vwoolf@university.edu", Bio = "Prof. Woolf has mentored thousands of writers and publishes regularly on modern composition pedagogy." }
            },
            new Course
            {
                Id = "eng201", Code = "ENG 201", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, democracy, and social change.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = "eng", IsFeatured = true,
                Instructor = new Instructor { Name = "Prof. Mark Twain", Title = "Professor", Email = "mtwain@university.edu", Bio = "Prof. Twain is a celebrated scholar of American literary history with a focus on 19th-century fiction and satire." }
            },
            new Course
            {
                Id = "phys101", Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes a weekly laboratory component with hands-on experiments.",
                Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM, Fri Lab 1:00–3:00 PM", DepartmentId = "phys",
                Instructor = new Instructor { Name = "Dr. Marie Curie", Title = "Professor", Email = "mcurie@university.edu", Bio = "Dr. Curie is a distinguished physicist with expertise in experimental methods and a passion for undergraduate education." }
            },
            new Course
            {
                Id = "hist101", Code = "HIST 101", Title = "World History to 1500",
                Description = "A global survey of human civilizations from prehistory to the early modern period, covering political, economic, and cultural developments.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = "hist",
                Instructor = new Instructor { Name = "Dr. Herodotus", Title = "Associate Professor", Email = "herodotus@university.edu", Bio = "Dr. Herodotus is a specialist in ancient civilizations with extensive fieldwork experience across the Mediterranean." }
            },
            new Course
            {
                Id = "hist201", Code = "HIST 201", Title = "Modern World History",
                Description = "Major events and movements from 1500 to the present, including colonialism, revolutions, world wars, and globalization.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = "hist",
                Instructor = new Instructor { Name = "Dr. Howard Zinn", Title = "Professor", Email = "hzinn@university.edu", Bio = "Dr. Zinn is known for his engaging lectures and research on social movements and grassroots history." }
            },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        IEnumerable<Course> query = _courses;

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));
}

