arguments.file_text:
@page "/courses"
@inject CourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-2 mb-4 align-items-end">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" class="form-control"
               placeholder="Search by title, code, or description…" value="@Search" />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select id="department" name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Department, Search);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">
        No courses match your criteria. Try adjusting your search or filter.
    </div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="list-group list-group-flush">
        @foreach (var course in courses)
        {
            <CourseListItem Course="course" />
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }
}

@page "/courses/{CourseId}"
@inject CourseCatalog.Services.ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-outline-primary">Back to Courses</a>
}
else
{
    <PageTitle>@course.Code @course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses?department=@course.DepartmentId">@departmentName</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="d-flex align-items-start justify-content-between mb-3">
        <div>
            <h1>@course.Code — @course.Title</h1>
            <span class="badge bg-primary me-1">@course.Credits Credits</span>
            <span class="badge bg-secondary">@departmentName</span>
        </div>
        <a href="enroll?courseId=@course.Id" class="btn btn-success">Enroll</a>
    </div>

    <section class="mb-4">
        <h4>Description</h4>
        <p>@course.Description</p>
    </section>

    <section class="mb-4">
        <h4>Schedule</h4>
        <p><span class="bi bi-clock"></span> @course.Schedule</p>
    </section>

    <section>
        <h4>Instructor</h4>
        <InstructorBio Instructor="course.Instructor" />
    </section>
}

@code {
    [Parameter]
    public string? CourseId { get; set; }

    private CourseCatalog.Models.Course? course;
    private string departmentName = "";

    protected override void OnParametersSet()
    {
        course = string.IsNullOrEmpty(CourseId) ? null : CatalogService.GetCourse(CourseId);
        if (course is not null)
        {
            departmentName = CatalogService.GetDepartment(course.DepartmentId)?.Name ?? course.DepartmentId;
        }
    }
}

@page "/enroll"
@inject CourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Request Enrollment</h1>
<p class="text-muted">Fill out the form below to request enrollment in a course.</p>

@if (Submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted</h4>
        <p>Thank you, <strong>@Model.FullName</strong> (ID: @Model.StudentId). Your enrollment request for
        <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title ?? Model.CourseId)</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will be notified by email once your request is processed.</p>
    </div>
    <a href="courses" class="btn btn-outline-primary">Browse More Courses</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />
        <ValidationSummary class="text-danger" />

        <div class="mb-3" style="max-width: 500px;">
            <label for="fullName" class="form-label">Full Name</label>
            <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
            <ValidationMessage For="() => Model.FullName" class="text-danger" />
        </div>

        <div class="mb-3" style="max-width: 500px;">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU-12345" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3" style="max-width: 500px;">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="">— Select a course —</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private bool Submitted { get; set; }

